{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C04"],
      "claim": "Kanamycin, a closely related aminoglycoside, appeared in cerebrospinal fluid in concentrations directly related to blood levels in animals, demonstrating that aminoglycosides can achieve CNS entry after systemic administration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Vidarabine, a polar glycoside-like nucleoside, achieved mean CSF/plasma ratios of 35% in humans, showing that polar carbohydrate-containing molecules can reach meaningful CSF concentrations.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Hydroxysafflor yellow A, a large polar glycoside, reached 1026 ng/g in rat brain and showed increased brain uptake under BBB disruption, supporting that large polar glycosides can access CNS under inflammatory conditions such as meningitis.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Fludarabine brain uptake is transporter-mediated and higher than related nucleosides, indicating that active transport can overcome poor passive permeability for glycoside-like molecules.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Pass: despite very unfavorable passive physicochemical properties, transferable experimental evidence from aminoglycosides and polar glycosides demonstrates meaningful CSF/brain entry, and meningitis-associated BBB disruption would further enhance CNS access.",
  "evidence_gaps": [
    "No direct CSF/plasma or brain concentration data for streptomycin itself.",
    "Kanamycin evidence lacks a quantitative CSF/plasma ratio or therapeutic adequacy assessment.",
    "Nucleoside transporter-mediated uptake may not be directly applicable to aminoglycosides.",
    "The degree of BBB disruption in meningitis is variable and may affect the extent of penetration."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "high",
      "card_ids": ["C04"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "aminoglycoside"
    },
