      "card_ids": ["C13", "C06", "C07", "C09", "C12"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "nucleoside"
    },
    {
      "applicability": "moderate",
      "card_ids": ["C05", "C01", "C03"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "glycoside"
    }
  ],
  "revision_action": "initial"
}

